    pub(crate) fn emit_call_rust_owner_result(&self, world: &EmitWorld<'_, '_, '_, '_>, func: &Expr) -> Option<(String, String)> {
        let name = match call_written_name(world.words, func) { Some(__nikaia_value) => __nikaia_value, None => return None };
        if self.own_contracts.functions.contains_key(&name) { return None; }
        let contract = match self.described.functions.get(&name) { Some(__nikaia_value) => __nikaia_value, None => return None };
        let signature = match contract.signature.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return None };
        let result = match signature.result.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return None };
        emit_rust_crossing(result, false, 0)
    }
    pub(crate) fn emit_call_sends_a_kept_value<H: EmitHost>(&self, host: &H, args: &[Expr]) -> bool {
        if !host.overlaps_user_code() { return false; }
        for arg in args.iter() { if self.facts.kept_args_run_async.contains_key(&node_key(arg)) { return true; } }
        false
    }
    pub(crate) fn emit_call_awaits_a_parameter(&self, func: &Expr, scope: &EmitScope) -> bool {
        match func {
            Expr::Variable(name, _) => { let name = *name; scope.awaited.contains(&name) },
            _ => false,
        }
    }
    // sync (Part II, 12.1): pure CPU, cannot pause. Checked before
    // this was written - see `contracts::sync`.
    #[allow(clippy::too_many_arguments)]
    pub(crate) fn emit_call_kept<H: EmitHost>(&self, world: &EmitWorld<'_, '_, '_, '_>, walk: &mut EmitWalk, out: &mut EmitOut, host: &H, func: &Expr, args: &[Expr], depth: i64, flow: EmitFlow, scope: &EmitScope) -> Result<bool, nikaia_std::error::Thrown<EmitRefused>> {
        Ok(match func {
            Expr::Variable(name, _) => {
                let name = *name;
                let key = node_key(func);
                if !self.facts.kept_calls.contains_key(&key) { return Ok(false); }
                let kept = match self.facts.kept_calls.get(&key) { Some(__nikaia_value) => __nikaia_value, None => return Ok(false) };
                let pauses = kept.0;
                let fails = kept.1;
                let how = nikaia_std::index::or(self.facts.narrowed_reads.get(&key), || -1);
                if how >= 0 {
                    self.emit_expr_narrowed(out, &EmitOut { buf: escaped_name(&emit_text(world, name)), entries: vec![], unsafe_depth: 0 }, how, false);
                    out.push("(");
                } else { out.push(&format!("{}(", escaped_name(&emit_text(world, name)))); }
                let mut at = 0;
                for arg in args.iter() {
                    if at > 0 { out.push(", "); }
                    at += 1;
                    let change = self.facts.mut_args.contains(&node_key(arg));
                    if change && self.facts.reborrowed_args.contains(&node_key(arg)) { out.push("&mut *"); } else if change { out.push("&mut "); } else if self.facts.lent_args.contains(&node_key(arg)) && !self.facts.views_handed_on.contains(&node_key(arg)) { out.push("&"); }
                    let (before, after) = emit_leaf_wrapped(&self.facts.nullable_args, node_key(arg))?;
                    out.push(&before);
                    self.emit_expr(world, walk, out, host, arg, depth, flow, scope)?;
                    out.push(&after);
                }
                out.push(")");
                if pauses { out.push(&emit_async_pause(&walk)); }
                if fails && flow.can_throw && !flow.caught {
                    out.push(&self.box_into_channel(world, scope));
                    out.push("?");
                }
                return Ok(true);
            },
            _ => return Ok(false),
        })
    }
