    pub(crate) fn emit_call_grammar<H: EmitHost>(&self, world: &EmitWorld<'_, '_, '_, '_>, walk: &mut EmitWalk, out: &mut EmitOut, host: &H, func: &Expr, args: &[Expr], config: &[ConfigArg], depth: i64, flow: EmitFlow, scope: &EmitScope) -> Result<bool, nikaia_std::error::Thrown<EmitRefused>> {
        Ok(match func {
            Expr::Path(segments, _) => {
                if args.is_empty() { return Ok(false); }
                if segments.len() == 2 && self.grammars.contains_key(&emit_text(world, *unsafe { nikaia_std::proven::read(&segments, (0) as usize) })) {
                    let parallelism = host.parallelism();
                    let mut values: Vec<Expr> = vec![];
                    for i in 1..args.len() as i64 { values.push((*unsafe { nikaia_std::proven::read(&args, (i) as usize) }).clone()); }
                    self.emit_core_grammar_entry(world, walk, out, host, *unsafe { nikaia_std::proven::read(&segments, (0) as usize) }, *unsafe { nikaia_std::proven::read(&segments, (1) as usize) }, unsafe { nikaia_std::proven::read(&args, (0) as usize) }, &values, config, &parallelism, depth, flow, scope)?;
                    return Ok(true);
                }
                if segments.len() != 3 && segments.len() != 2 { return Ok(false); }
                let first = unsafe { nikaia_std::proven::sub::<i64>(segments.len() as i64, 2) };
                let package = match first {
                    0 => String::from(""),
                    _ => format!("{}::", emit_text(world, *unsafe { nikaia_std::proven::read(&segments, (0) as usize) })),
                };
                let book = emit_text(world, *unsafe { nikaia_std::proven::read(&segments, (first) as usize) });
                let rule = emit_text(world, *unsafe { nikaia_std::proven::read(&segments, (nikaia_std::proven::add::<i64>(first, 1)) as usize) });
                if !self.a_package_grammar_entry(&format!("{}{}::{}", package, book, rule)) { return Ok(false); }
                let mut question: &'static str = "?";
                if flow.caught { question = ""; }
                let mut pieces = false;
                let mut streamed = false;
                let mut stream_item: String = String::from("");
                let mut options: Vec<String> = nikaia_std::block::list(nikaia_std::block::Place::Block);
                let contract = self.own_contracts.functions.get(&format!("{}{}::{}", package, book, rule));
                if contract.is_some() {
                    let held = match contract { Some(__nikaia_value) => __nikaia_value, None => return Ok(false) };
                    pieces = held.pieces;
                    match &held.signature {
                        Some(signature) => {
                            match &signature.result {
                                Some(result) => {
                                    streamed = a_sequence_type(result);
                                    stream_item = match result {
                                        Ty::Seq { item, .. } => { let item = nikaia_std::boxed::open(item); match item {
                                            Ty::Named { name, .. } => nikaia_std::block::Text::from(name.to_string()),
                                            _ => String::from(""),
                                        } },
                                        _ => String::from(""),
                                    };
                                },
                                None => { },
                            }
                            options.reserve(signature.config.iter().size_hint().0); for option in signature.config.iter() { options.push(nikaia_std::block::Text::from(option.name.to_string())); }
                        },
                        None => { },
                    }
                }
                if streamed {
                    let each_body: Option<EmitOut> = match walk.each_body {
                        None => None,
                        Some(ref held) => Some(held.clone()),
                    };
                    walk.each_body = None;
                    if each_body.is_some() {
                        out.push(&format!("{}{}(::std::convert::AsRef::<[u8]>::as_ref(&*", package, emit_stream_each_name(&book, &rule)));
                        self.emit_expr(world, walk, out, host, unsafe { nikaia_std::proven::read(&args, (0) as usize) }, depth, flow, scope)?;
                        out.push(")");
                    } else {
                        if self.emit_stream_item_views(&stream_item) { self.emit_stream_thread_refused(&walk, &format!("{}{}::{}", package, book, rule), &stream_item, Some(flow.statement))?; }
                        out.push(&format!("Ok::<_, nikaia_std::grammar::ParseError>({}{}(::std::convert::AsRef::<[u8]>::as_ref(&*", package, emit_stream_walk_name(&book, &rule)));
                        self.emit_expr(world, walk, out, host, unsafe { nikaia_std::proven::read(&args, (0) as usize) }, depth, flow, scope)?;
                        out.push(").to_vec()");
                    }
                    for i in 1..args.len() as i64 {
                        out.push(", ");
                        self.emit_expr(world, walk, out, host, unsafe { nikaia_std::proven::read(&args, (i) as usize) }, depth, flow, scope)?;
                    }
                    for option in options.iter() {
                        let mut given = false;
                        for c in config.iter() {
                            if !given && emit_text(world, c.name) == *option {
                                out.push(", ::std::option::Option::Some(");
                                self.emit_expr(world, walk, out, host, &c.value, depth, flow, scope)?;
                                out.push(")");
                                given = true;
                            }
                        }
                        if !given { out.push(", ::std::option::Option::None"); }
                    }
                    let mut table = false;
                    for c in config.iter() {
                        if !table && emit_text(world, c.name) == "words" && !nikaia_std::list::contains(&options, &"words") {
                            out.push(", ::std::option::Option::Some(nikaia_std::winnow_grammar::InternerContext::clone(&");
                            self.emit_expr(world, walk, out, host, &c.value, depth, flow, scope)?;
                            out.push("))");
                            table = true;
                        }
                    }
                    if !table { out.push(", ::std::option::Option::None"); }
                    match each_body {
                        None => { out.push(&format!(")){}", question)); },
                        Some(ref body) => { out.push_around(&format!(", |__wg_one| {{ __NIKAIA_EACH_BODY__ }}){}", question), "__NIKAIA_EACH_BODY__", body); },
                    }
                    return Ok(true);
                }
                if args.len() != 1 { return Ok(false); }
                if pieces {
                    out.push("nikaia_std::grammar::parse_pieces(&*");
                    self.emit_expr(world, walk, out, host, unsafe { nikaia_std::proven::read(&args, (0) as usize) }, depth, flow, scope)?;
                    let options = emit_fold_options(&book, &rule);
                    let claimed = host.parallelism() != "Parallelism::Off";
                    out.push(&format!(", {}{}(), {}, |source, how| {}{}::parse_{}_pieces(source, &winnow_grammar::ParseContext::<()>::default(), how)){}", package, options, claimed, package, book, rule, question));
                    return Ok(true);
                }
                let mut table: Option<Expr> = None;
                for c in config.iter() { if emit_text(world, c.name) == "words" && !nikaia_std::list::contains(&options, &"words") { table = Some(c.value.clone()); } }
                match table {
                    Some(ref words) => {
                        out.push("nikaia_std::grammar::parse_in(&*");
                        self.emit_expr(world, walk, out, host, unsafe { nikaia_std::proven::read(&args, (0) as usize) }, depth, flow, scope)?;
                        out.push(", &");
                        self.emit_expr(world, walk, out, host, words, depth, flow, scope)?;
                    },
                    None => {
                        out.push("nikaia_std::grammar::parse(&*");
                        self.emit_expr(world, walk, out, host, unsafe { nikaia_std::proven::read(&args, (0) as usize) }, depth, flow, scope)?;
                    },
                }
                out.push(&format!(", {}{}::parse_{}()){}", package, book, rule, question));
                return Ok(true);
            },
            _ => return Ok(false),
        })
    }
